/* =============================================
   VIDEO POSITION CONTROL
   Change the two % values below to reposition:
   First  value = horizontal  (0%=left  50%=center  100%=right)
   Second value = vertical    (0%=top   50%=center  100%=bottom)
   Example: 50% 30%  means centered horizontally, 30% from top
   ============================================= */
selector .elementor-background-video-container { overflow:hidden; }
selector .elementor-background-video-container video { object-fit:cover; object-position:50% 50%; width:100%; height:100%; }
selector .elementor-background-video-embed { object-fit:cover; object-position:50% 50%; }
/* ============================================= */
@keyframes h-twinkle{0%,100%{opacity:0;transform:scale(.4);}50%{opacity:1;transform:scale(1);}} @keyframes h-float{0%,100%{transform:translateY(0);}50%{transform:translateY(-18px);}} @keyframes h-ring-cw{from{transform:rotate(0deg);}to{transform:rotate(360deg);}} @keyframes h-ring-ccw{from{transform:rotate(0deg);}to{transform:rotate(-360deg);}} @keyframes h-pulse{0%,100%{opacity:.35;}50%{opacity:.85;}} @keyframes h-gold{0%{background-position:0% 50%;}50%{background-position:100% 50%;}100%{background-position:0% 50%;}} .hs{position:absolute;border-radius:50%;background:#fff;animation:h-twinkle var(--d,3s) var(--dl,0s) ease-in-out infinite;} .h1x{font-family:'Playfair Display',serif;font-size:clamp(40px,5vw,82px);font-weight:400;line-height:1.04;letter-spacing:-2px;margin:0 0 20px;background:linear-gradient(130deg,#fff 0%,#f5e6c0 28%,#d4a853 52%,#f0d080 75%,#fff 100%);background-size:300% 300%;-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;animation:h-gold 7s ease-in-out 1.5s infinite;} .h-lbl{display:inline-flex;align-items:center;gap:12px;font-family:'Inter',sans-serif;font-size:14px;font-weight:800;letter-spacing:7px;text-transform:uppercase;color:#f0d080;text-shadow:0 0 15px rgba(240,208,128,0.5);margin-bottom:22px;} .h-sub{font-family:'Inter',sans-serif;font-size:clamp(10px,1.1vw,14px);color:rgba(255,255,255,.45);letter-spacing:2.5px;text-transform:uppercase;margin:0 0 28px;} .h-div{width:44px;height:1px;background:linear-gradient(90deg,#d4a853,transparent);margin-bottom:28px;} .h-ga{display:inline-flex;align-items:center;padding:16px 36px;background:linear-gradient(135deg,#d4a853,#b8893a);color:#050810;font-family:'Inter',sans-serif;font-size:11px;font-weight:700;letter-spacing:2.5px;text-transform:uppercase;border-radius:6px;text-decoration:none;transition:all .35s ease;margin-right:14px;box-shadow:0 8px 28px rgba(212,168,83,.3);} .h-ga:hover{box-shadow:0 0 48px rgba(212,168,83,.55);transform:translateY(-3px);} .h-gb{display:inline-flex;align-items:center;padding:16px 32px;background:rgba(255,255,255,.04);color:rgba(255,255,255,.8);font-family:'Inter',sans-serif;font-size:11px;font-weight:700;letter-spacing:2.5px;text-transform:uppercase;border-radius:6px;border:1px solid rgba(255,255,255,.18);text-decoration:none;backdrop-filter:blur(12px);transition:all .3s ease;} .h-gb:hover{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.4);} .h-webinar-badge{display:inline-flex;align-items:center;gap:8px;background:rgba(212,168,83,.08);border:1px solid rgba(212,168,83,.25);border-radius:999px;padding:6px 16px;font-family:'Inter',sans-serif;font-size:9px;font-weight:700;letter-spacing:3px;text-transform:uppercase;color:#d4a853;margin-bottom:16px;}
